rows=[]
def add(kind,id,version,title,prompt,correct,wrong,why,chapter='',source='platform authored companion practice'):
 options=[correct,*wrong]
 assert len(set(options))==len(options)
 options=sorted(options,key=lambda x:hashlib.sha256((id+x).encode()).hexdigest())
 rows.append({'id':f'{kind}:{id}','version':'v1','materials':[{'kind':kind,'id':id,'version':version}], 'chapter_title':chapter,'title':title,'prompt':prompt,'options':[{'id':str(i),'label':x}for i,x in enumerate(options)],'correct_option_id':str(options.index(correct)),'explanation':why,'review':{'source':source,'checked_at':'2026-10-15','recheck_by':'2027-04-16','checked_by':'Codex authored comprehension audit; not clinical review'}})
