for cid,v in LATEST_VERSIONS.items():
 c=course(cid,v)
 for l in c['lessons']:
  ch=l.get('chapter') or l['title']
  if cid in ('java','java-backend','go'):
   if l['id']not in manual:continue
   prompt,correct,wrong,why=manual[l['id']]
   add('lesson',cid+':'+l['id'],v,l['title'],prompt,correct,wrong,why,ch,'Public authored course '+cid+'/'+v)
  else:
   vocab=l.get('vocabulary',[])
   if not vocab:raise ValueError('Missing vocabulary '+l['id'])
   word=vocab[0];wrong=list(dict.fromkeys(x['translation']for x in vocab if x['translation']!=word['translation']))[:2]
   assert len(wrong)==2
   prompt=f"Выберите значение «{word['word']}» в примере: {word['example']}"
   add('lesson',cid+':'+l['id'],v,l['title'],prompt,word['translation'],wrong,f"В этом примере «{word['word']}» означает «{word['translation']}».",ch,'Public authored vocabulary '+cid+'/'+v)
cat=load_recipes()
for r in cat['recipes']:
 steps=r['steps'];wrong=list(dict.fromkeys(steps[1:]))[:2]
 if len(wrong)<2:wrong+=['Пропустить подготовку продуктов']
 add('recipe',r['id'],cat['version'],r['name'],'Какое действие выполняется первым в этом рецепте?',steps[0],wrong[:2],'Сначала: '+steps[0]+' Затем: '+steps[1],source='Public authored recipe '+r['id'])
ex=json.loads((ROOT/'exercises.json').read_text())
for id,prompt,correct,wrong,why in [
 ('chair_squat','Как завершить опускание к стулу?','Мягко коснуться сиденья и встать с опорой на всю стопу',['Резко упасть на сиденье','Перенести всю опору на носки'],'Контролируйте опускание и сохраняйте опору на всю стопу.'),
 ('wall_pushup','На какой высоте поставить ладони при отжимании от стены?','На уровне груди',['Выше головы','У самого пола'],'Исходная техника описывает ладони на уровне груди.'),
 ('bird_dog','Что важно сохранять при разгибании противоположных руки и ноги?','Устойчивое положение корпуса',['Резкие повороты таза','Максимальный прогиб поясницы'],'Движение выполняется спокойно, с контролем корпуса.')]:
 assert id in ex['exercises'];add('exercise',id,ex['version'],ex['exercises'][id]['name'],prompt,correct,wrong,why,source=ex['exercises'][id]['source'])
(ROOT/'assistant-learning-v1.json').write_text(json.dumps({'version':'v1','checks':rows},ensure_ascii=False,indent=2)+'\n')
print('Authored checks:',len(rows))
